package edu.bis701.exp07;
import java.sql.*;
public class HiveExperiment{public static void main(String[]a)throws Exception{String url=System.getenv().getOrDefault("HIVE_JDBC_URL","jdbc:hive2://localhost:10000/default");String user=System.getenv().getOrDefault("HIVE_USER","");String pass=System.getenv().getOrDefault("HIVE_PASSWORD","");try(Connection c=DriverManager.getConnection(url,user,pass);Statement s=c.createStatement()){String dataPath=(a.length>0?a[0]:"data/employees.tsv").replace("\\","/").replace("'","\\'");String[]sql={"CREATE DATABASE IF NOT EXISTS bis701_lab","USE bis701_lab","CREATE TABLE IF NOT EXISTS employees (id INT, name STRING, age INT, city STRING, salary DOUBLE) ROW FORMAT DELIMITED FIELDS TERMINATED BY '\\t' STORED AS TEXTFILE","LOAD DATA LOCAL INPATH '"+dataPath+"' OVERWRITE INTO TABLE employees","CREATE OR REPLACE VIEW employee_city_view AS SELECT city, COUNT(*) AS employee_count, AVG(salary) AS average_salary FROM employees GROUP BY city","ALTER TABLE employees ADD COLUMNS (email STRING)","CREATE INDEX employee_city_idx ON TABLE employees (city) AS 'org.apache.hadoop.hive.ql.index.compact.CompactIndexHandler' WITH DEFERRED REBUILD"};for(String q:sql){System.out.println("HiveQL> "+q);try{s.execute(q);}catch(SQLException e){System.err.println("Statement note: "+e.getMessage());}}try(ResultSet r=s.executeQuery("SELECT city, COUNT(*) AS employee_count, AVG(salary) AS average_salary FROM employees GROUP BY city")){while(r.next())System.out.printf("%s\t%d\t%.2f%n",r.getString(1),r.getInt(2),r.getDouble(3));}}}}
